r'''struct PacketSpan{std::size_t begin;std::size_t size;};struct PacketLayout{PacketSpan first;PacketSpan second;};class TwoSpanPacketLedger{public:explicit TwoSpanPacketLedger(std::size_t);std::optional<std::uint32_t> stage(std::vector<std::uint8_t>);std::optional<PacketLayout> spans(std::uint32_t)const;bool consume(std::uint32_t);private:struct Desc{std::uint32_t id;PacketLayout layout;std::size_t length;};std::vector<std::uint8_t> bytes_;std::deque<Desc> packets_;std::size_t head_=0;std::size_t tail_=0;std::size_t used_=0;std::uint32_t next_=1;};''',
r'''TwoSpanPacketLedger::TwoSpanPacketLedger(std::size_t){throw std::logic_error("not implemented");}std::optional<std::uint32_t> TwoSpanPacketLedger::stage(std::vector<std::uint8_t>){throw std::logic_error("not implemented");}std::optional<PacketLayout> TwoSpanPacketLedger::spans(std::uint32_t)const{throw std::logic_error("not implemented");}bool TwoSpanPacketLedger::consume(std::uint32_t){throw std::logic_error("not implemented");}''',
r'''TwoSpanPacketLedger::TwoSpanPacketLedger(std::size_t n):bytes_(n){if(!n)throw std::invalid_argument("capacity");}std::optional<std::uint32_t> TwoSpanPacketLedger::stage(std::vector<std::uint8_t> p){if(p.empty()||p.size()>bytes_.size()-used_)return std::nullopt;std::size_t first=std::min(p.size(),bytes_.size()-tail_),second=p.size()-first;std::copy_n(p.begin(),static_cast<std::ptrdiff_t>(first),bytes_.begin()+static_cast<std::ptrdiff_t>(tail_));std::copy(p.begin()+static_cast<std::ptrdiff_t>(first),p.end(),bytes_.begin());PacketLayout layout{{tail_,first},{0,second}};packets_.push_back({next_,layout,p.size()});tail_=(tail_+p.size())%bytes_.size();used_+=p.size();return next_++;}std::optional<PacketLayout> TwoSpanPacketLedger::spans(std::uint32_t id)const{for(const auto&p:packets_)if(p.id==id)return p.layout;return std::nullopt;}bool TwoSpanPacketLedger::consume(std::uint32_t id){if(packets_.empty()||packets_.front().id!=id)return false;head_=(head_+packets_.front().length)%bytes_.size();used_-=packets_.front().length;packets_.pop_front();return true;}''',
r'''int main(){TwoSpanPacketLedger s(7);auto a=s.stage({1,2,3,4,5});CHECK(a&&s.consume(*a));auto b=s.stage({6,7,8,9});auto l=s.spans(*b);CHECK(l&&l->first.size==2&&l->second.size==2);return failures;}''',
r'''int main(){TwoSpanPacketLedger s(3);CHECK(!s.stage({}));auto a=s.stage({1,2});auto b=s.stage({3});CHECK(a&&b);CHECK(!s.consume(*b));CHECK(s.consume(*a));CHECK(s.consume(*b));return failures;}''',
