r'''class CrossWordSymbolPack{public:CrossWordSymbolPack(std::size_t,std::uint8_t);bool push(std::uint32_t);std::optional<std::uint32_t> pop();std::vector<std::uint32_t> values()const;private:std::size_t cap_;std::uint8_t width_;std::vector<std::uint64_t> words_;std::size_t head_=0;std::size_t count_=0;void write(std::size_t,std::uint32_t);std::uint32_t read(std::size_t)const;};''',
r'''CrossWordSymbolPack::CrossWordSymbolPack(std::size_t,std::uint8_t):cap_(0),width_(0){throw std::logic_error("not implemented");}bool CrossWordSymbolPack::push(std::uint32_t){throw std::logic_error("not implemented");}std::optional<std::uint32_t> CrossWordSymbolPack::pop(){throw std::logic_error("not implemented");}std::vector<std::uint32_t> CrossWordSymbolPack::values()const{throw std::logic_error("not implemented");}void CrossWordSymbolPack::write(std::size_t,std::uint32_t){}std::uint32_t CrossWordSymbolPack::read(std::size_t)const{throw std::logic_error("not implemented");}''',
r'''CrossWordSymbolPack::CrossWordSymbolPack(std::size_t n,std::uint8_t w):cap_(n),width_(w),words_((n*w+63)/64){if(!n||w<1||w>17)throw std::invalid_argument("shape");}void CrossWordSymbolPack::write(std::size_t slot,std::uint32_t v){std::size_t bit=slot*width_,word=bit/64,shift=bit%64;std::uint64_t mask=(std::uint64_t{1}<<width_)-1;words_[word]=(words_[word]&~(mask<<shift))|(static_cast<std::uint64_t>(v)<<shift);if(shift+width_>64){std::size_t high=64-shift;std::uint64_t upper=v>>high;std::uint64_t upper_mask=(std::uint64_t{1}<<(width_-high))-1;words_[(word+1)%words_.size()]=(words_[(word+1)%words_.size()]&~upper_mask)|upper;}}std::uint32_t CrossWordSymbolPack::read(std::size_t slot)const{std::size_t bit=slot*width_,word=bit/64,shift=bit%64;std::uint64_t value=words_[word]>>shift;if(shift+width_>64)value|=words_[(word+1)%words_.size()]<<(64-shift);return static_cast<std::uint32_t>(value&((std::uint64_t{1}<<width_)-1));}bool CrossWordSymbolPack::push(std::uint32_t v){if(v>=(std::uint32_t{1}<<width_))throw std::invalid_argument("value");if(count_==cap_)return false;write((head_+count_)%cap_,v);++count_;return true;}std::optional<std::uint32_t> CrossWordSymbolPack::pop(){if(!count_)return std::nullopt;auto v=read(head_);head_=(head_+1)%cap_;--count_;return v;}std::vector<std::uint32_t> CrossWordSymbolPack::values()const{std::vector<std::uint32_t> out;for(std::size_t i=0;i<count_;++i)out.push_back(read((head_+i)%cap_));return out;}''',
r'''int main(){CrossWordSymbolPack p(5,17);CHECK(p.push(1));CHECK(p.push(2));CHECK(p.push(3));CHECK(p.push(131071));CHECK(p.values()==std::vector<std::uint32_t>({1,2,3,131071}));return failures;}''',
r'''int main(){CrossWordSymbolPack p(2,3);CHECK(p.push(7));CHECK(p.push(0));CHECK(!p.push(1));CHECK(p.pop()==7);CHECK(p.push(5));CHECK(p.values()==std::vector<std::uint32_t>({0,5}));try{p.push(8);CHECK(false);}catch(const std::invalid_argument&){}return failures;}''',
