r'''class OriginMappedRowGrid{public:OriginMappedRowGrid(std::size_t,std::size_t,std::size_t);bool replace(std::size_t,std::vector<int>);std::vector<int> column(std::size_t)const;void rotate_rows(std::int64_t);std::vector<int> padding()const;private:std::size_t rows_;std::size_t cols_;std::size_t stride_;std::size_t origin_=0;std::vector<int> cells_;std::size_t physical(std::size_t)const;};''',
r'''OriginMappedRowGrid::OriginMappedRowGrid(std::size_t,std::size_t,std::size_t):rows_(0),cols_(0),stride_(0){throw std::logic_error("not implemented");}bool OriginMappedRowGrid::replace(std::size_t,std::vector<int>){throw std::logic_error("not implemented");}std::vector<int> OriginMappedRowGrid::column(std::size_t)const{throw std::logic_error("not implemented");}void OriginMappedRowGrid::rotate_rows(std::int64_t){throw std::logic_error("not implemented");}std::vector<int> OriginMappedRowGrid::padding()const{throw std::logic_error("not implemented");}std::size_t OriginMappedRowGrid::physical(std::size_t)const{throw std::logic_error("not implemented");}''',
r'''OriginMappedRowGrid::OriginMappedRowGrid(std::size_t r,std::size_t c,std::size_t s):rows_(r),cols_(c),stride_(s),cells_(r*s,-777){if(!r||!c||s<c)throw std::invalid_argument("shape");for(std::size_t y=0;y<r;++y)for(std::size_t x=0;x<c;++x)cells_[y*s+x]=0;}std::size_t OriginMappedRowGrid::physical(std::size_t logical)const{return (origin_+logical)%rows_;}bool OriginMappedRowGrid::replace(std::size_t row,std::vector<int> v){if(row>=rows_||v.size()!=cols_)throw std::invalid_argument("row");auto p=physical(row);std::copy(v.begin(),v.end(),cells_.begin()+static_cast<std::ptrdiff_t>(p*stride_));return true;}std::vector<int> OriginMappedRowGrid::column(std::size_t c)const{if(c>=cols_)throw std::invalid_argument("column");std::vector<int> out;for(std::size_t r=0;r<rows_;++r)out.push_back(cells_[physical(r)*stride_+c]);return out;}void OriginMappedRowGrid::rotate_rows(std::int64_t n){auto m=n%static_cast<std::int64_t>(rows_);if(m<0)m+=static_cast<std::int64_t>(rows_);origin_=(origin_+rows_-static_cast<std::size_t>(m))%rows_;}std::vector<int> OriginMappedRowGrid::padding()const{std::vector<int> out;for(std::size_t r=0;r<rows_;++r)for(std::size_t c=cols_;c<stride_;++c)out.push_back(cells_[r*stride_+c]);return out;}''',
r'''int main(){OriginMappedRowGrid g(3,2,4);g.replace(0,{1,2});g.replace(1,{3,4});g.replace(2,{5,6});g.rotate_rows(-1);CHECK(g.column(0)==std::vector<int>({3,5,1}));g.replace(0,{9,8});CHECK(g.column(1)==std::vector<int>({8,6,2}));CHECK(g.padding()==std::vector<int>({-777,-777,-777,-777,-777,-777}));return failures;}''',
r'''int main(){OriginMappedRowGrid g(2,1,3);g.rotate_rows(5);g.replace(0,{7});CHECK(g.column(0)==std::vector<int>({7,0}));try{g.replace(2,{1});CHECK(false);}catch(const std::invalid_argument&){}return failures;}''',
